(() => {
 const D=window.TERRA,U=window.REGION_UI;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const maps=window.TERRA_MAPS||{default:'original',maps:{original:window.TERRA_MAP_REFERENCE}};
 let mapMode;try{mapMode=localStorage.getItem('terra-map-source');}catch{}
 if(!maps.maps[mapMode])mapMode=maps.default;
 let reference,frame,positions;
 function configureMap(){reference=maps.maps[mapMode];const height=1140*reference.height/reference.width;frame={x:30,y:(760-height)/2,width:1140,height};positions=Object.fromEntries(Object.entries(reference.positions).filter(([,p])=>p).map(([id,p])=>[id,[frame.x+p[0]*frame.width,frame.y+p[1]*frame.height]]));}
 configureMap();

 let selected='rhodes',storyId=null,phase=0,zoom=1,pan={x:0,y:0},fit=1,full=false,read={},links=false;
 const stories=id=>D.stories.filter(s=>s.region===id);
 const current=()=>stories(selected).find(s=>s.id===storyId)||stories(selected)[0];
 function connectionTargets(){const s=current();if(!s)return [];const names=new Set(s.people.map(x=>window.PERSON_BIOGRAPHIES.recordToPerson[window.ROSTER_RENDER.byName(x[0])?.id]||x[0]));return D.regions.filter(r=>r.id!==selected&&stories(r.id).some(t=>t.people.some(x=>names.has(window.PERSON_BIOGRAPHIES.recordToPerson[window.ROSTER_RENDER.byName(x[0])?.id]||x[0]))));}
 function land(){return `<img class="map-reference-image" src="${reference.src}" alt="${esc(reference.alt)}" style="left:${frame.x}px;top:${frame.y}px;width:${frame.width}px;height:${frame.height}px" width="${reference.width}" height="${reference.height}" draggable="false"><svg class="map-land" viewBox="0 0 1200 760" aria-hidden="true"><g id="map-connections"></g></svg>`;}

 function render(id,prefs,progress){selected=D.regions.some(r=>r.id===id)?id:selected;document.body.classList.remove('map-expanded');full=prefs.full;read=progress;const s=current();storyId=s?.id;phase=Math.min(phase,U.periods(s).length-1);return `<section class="operations-map"><div class="map-topbar"><div><div class="map-kicker"><span class="live-dot"></span>TERRA / CHRONICLE OPERATIONS</div><h1>大地行纪图</h1><p>选择地区，查阅事件阶段与相关人物。</p></div><div class="map-top-actions"><button class="map-list-link" data-action="toggle-full">${full?'低剧透导览':'完整事件时间轴'}</button><a class="map-list-link" href="#/atlas">篇章目录 ↗</a></div></div><div class="map-console"><div class="map-stage" id="map-stage" role="region" aria-label="可拖动缩放的泰拉地区地图" data-map-mode="${mapMode}"><div class="map-world" id="map-world">${land()}${D.regions.filter(r=>positions[r.id]).map((r,i)=>{const p=positions[r.id];return `<button class="map-node ${r.id===selected?'selected':''}" style="left:${p[0]}px;top:${p[1]}px;--node-accent:${r.color}" data-map-region="${r.id}" aria-pressed="${r.id===selected}" aria-label="选择${esc(r.name)}"><span class="node-symbol"><b>${r.glyph}</b></span><span class="node-caption"><small>${String(D.regions.indexOf(r)+1).padStart(2,'0')} / ${stories(r.id).length} 篇</small><strong>${esc(r.name)}</strong></span>${stories(r.id).every(s=>read[s.id]?.done)?'<i class="node-read" title="本地区篇章已读">✓</i>':''}</button>`;}).join('')}</div><details class="map-unplaced"><summary>其他地区与移动组织 · ${D.regions.filter(r=>!positions[r.id]).length}</summary><div>${D.regions.filter(r=>!positions[r.id]).map(r=>`<button data-map-region="${r.id}" aria-pressed="${r.id===selected}" class="${r.id===selected?'selected':''}">${esc(r.name)} <span>↗</span></button>`).join('')}</div><p>本版地图未标定的位置，保留为阅读入口。</p></details><div class="map-scanline" aria-hidden="true"></div><div class="map-corner top-left" aria-hidden="true"></div><div class="map-corner bottom-right" aria-hidden="true"></div><div class="map-controls"><button data-map-zoom="in" aria-label="放大地图">＋</button><button data-map-zoom="out" aria-label="缩小地图">−</button><button data-map-zoom="reset" aria-label="重置地图">复位</button><button data-map-fullscreen aria-label="展开全屏地图">全屏</button><span id="map-scale" aria-live="polite">100%</span></div><div class="map-locator"><span>地区快速定位</span><select id="map-region-select" aria-label="快速选择地图地区">${D.regions.map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="map-source-switch" role="group" aria-label="切换地图底图">${Object.entries(maps.maps).map(([key,m])=>`<button data-map-source="${key}" aria-pressed="${key===mapMode}">${esc(m.label)}</button>`).join('')}<small>${esc(reference.credit)}</small></div><div class="map-legend"><button id="map-link-toggle" data-map-links aria-pressed="${links}"><i></i>共有人物连线 ${links?'开':'关'}</button><span>拖动平移 · 滚轮缩放</span></div></div><aside class="map-event-panel" id="map-event-panel" aria-label="所选地区事件详情"></aside></div><p class="map-disclaimer">${mapMode==='clear'?`底图：<a href="${reference.sourcePage}" target="_blank" rel="noopener noreferrer">terminator7211、陈谈 · 无雾社区参考图 ↗</a>，据《大地巡旅》书衣整理，非官方原图。`:`底图：<a href="${reference.sourcePage}" target="_blank" rel="noopener noreferrer">官方游戏地图 · PRTS 转存 ↗</a>，保留原生迷雾。`} <a href="${reference.src}" target="_blank" rel="noopener noreferrer">查看高清全图（${reference.width} × ${reference.height}）↗</a> · <a href="https://prts.wiki/w/泰拉大典:地理" target="_blank" rel="noopener noreferrer">PRTS 地理互动图 ↗</a>。初始视图对准诸国区域，可拖动浏览全图。节点为地区入口，沿用各图资料时点；移动城市不作实时定位。未标定地区单列，共有人物连线表示共同出场人物。</p></section>`;}
 function panel(){const r=D.regions.find(r=>r.id===selected),ss=stories(selected),s=current(),ps=U.periods(s),p=ps[phase];document.getElementById('map-event-panel').innerHTML=`<div class="map-panel-head"><div class="map-kicker">REGIONAL RECORD / ${String(D.regions.indexOf(r)+1).padStart(2,'0')}</div><h2>${esc(r.name)}<span>${r.glyph}</span></h2><p>${esc(r.en)}</p></div>${ss.length>1?`<div class="map-story-tabs" aria-label="地区篇章">${ss.map(x=>`<button data-map-story="${x.id}" aria-pressed="${x.id===s.id}" class="${x.id===s.id?'selected':''}">${esc(x.title)}</button>`).join('')}</div>`:''}<div class="map-record-summary"><h3>${esc(s.title)}</h3><p>${esc(full?s.intro:r.deck)}</p>${s.origins?`<a class="map-history-entry" href="${window.ORIGIN_UI.firstHref(s)}">从地区起源与沿革读起 ↗</a>`:''}<div class="map-record-stats"><span>${ps.length} 个事件阶段</span>${s.origins?`<span>${s.origins.periods.length} 个沿革阶段</span>`:''}<span>${s.people.length} 位相关人物</span><span>${read[s.id]?.done?'已读完':'待阅读'}</span></div></div>${!positions[selected]?`<p class="map-location-note">${selected==='rhodes'?'罗德岛持续移动，本入口不代表固定驻地。':selected==='durin'?'杜林聚居地分布于地下，本入口不代表统一的地表国土。':'本版底图未标定该地区的位置，仍可在此阅读完整纪事。'}</p>`:''}${full?`<div class="map-timeline" role="group" aria-label="按阶段选择事件">${ps.map((x,i)=>`<button data-map-phase="${i}" class="${i===phase?'selected':''}" aria-pressed="${i===phase}"><i></i><span><small>${esc(x.period)}</small>${esc(x.title)}</span></button>`).join('')}</div><article class="map-active-event"><div class="map-kicker">EVENT ${String(phase+1).padStart(2,'0')} / ${String(ps.length).padStart(2,'0')}</div><h3>${esc(p.title)}</h3><p>${esc(p.body.slice(0,170))}${p.body.length>170?'……':''}</p>${window.STORY_IMAGE_UI.preview(s,phase)}<div class="map-event-people">${U.peopleLinks(p.people)}</div><a class="map-read-event" href="#/story/${s.id}/part-${phase}">阅读这一阶段 <span>→</span></a></article>`:`<div class="map-spoiler-note"><p>事件时间轴含关键转折与人物命运。</p><button data-action="enable-full">开启完整时间轴 →</button></div>`}<a class="map-read-all" href="#/story/${s.id}">进入地区纪事 <span>↗</span></a>`;drawConnections();}
 function drawConnections(){const el=document.getElementById('map-connections');if(!el)return;const a=positions[selected];if(!a){el.innerHTML='';return;}el.innerHTML=links?connectionTargets().filter(r=>positions[r.id]).map(r=>{const b=positions[r.id];return `<path d="M${a[0]} ${a[1]} Q${(a[0]+b[0])/2} ${Math.min(a[1],b[1])-50} ${b[0]} ${b[1]}" fill="none" stroke="#e8bc69" stroke-width="1.2" stroke-dasharray="6 7" opacity=".55"/>`;}).join(''):'';}
 function transform(){const w=document.getElementById('map-world');if(!w)return;const stage=document.getElementById('map-stage');const scale=fit*zoom;w.style.setProperty('--pin-scale',1/(scale||1));w.style.transform=`translate(${stage.clientWidth/2-600*scale+pan.x}px,${stage.clientHeight/2-380*scale+pan.y}px) scale(${scale})`;document.getElementById('map-scale').textContent=Math.round(zoom*100)+'%';}
 function zoomAt(next,x,y){const stage=document.getElementById('map-stage');if(!stage)return;next=Math.max(.7,Math.min(4.5,next));const ratio=next/zoom;pan={x:x-stage.clientWidth/2-(x-stage.clientWidth/2-pan.x)*ratio,y:y-stage.clientHeight/2-(y-stage.clientHeight/2-pan.y)*ratio};zoom=next;transform();}
 function activate(){const stage=document.getElementById('map-stage');if(!stage)return;fit=Math.min(stage.clientWidth/1200,stage.clientHeight/760)*.97;zoom=1;pan={x:0,y:0};transform();panel();let drag=null,pinch=null;const points=new Map();stage.addEventListener('pointerdown',e=>{if(e.target.closest('button,select,a,details'))return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});stage.setPointerCapture(e.pointerId);if(points.size===1)drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};if(points.size===2){const p=[...points.values()],rect=stage.getBoundingClientRect();pinch={distance:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),zoom,pan:{...pan},x:(p[0].x+p[1].x)/2-rect.left,y:(p[0].y+p[1].y)/2-rect.top};drag=null;}stage.classList.add('dragging');});stage.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===2&&pinch){const p=[...points.values()],rect=stage.getBoundingClientRect(),distance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),next=Math.max(.7,Math.min(4.5,pinch.zoom*distance/pinch.distance)),ratio=next/pinch.zoom;pan={x:(p[0].x+p[1].x)/2-rect.left-stage.clientWidth/2-(pinch.x-stage.clientWidth/2-pinch.pan.x)*ratio,y:(p[0].y+p[1].y)/2-rect.top-stage.clientHeight/2-(pinch.y-stage.clientHeight/2-pinch.pan.y)*ratio};zoom=next;transform();}else if(drag){pan={x:drag.px+e.clientX-drag.x,y:drag.py+e.clientY-drag.y};transform();}});const end=e=>{points.delete(e.pointerId);pinch=null;drag=null;stage.classList.remove('dragging');};stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);stage.addEventListener('wheel',e=>{if(e.target.closest('details'))return;e.preventDefault();const r=stage.getBoundingClientRect();zoomAt(zoom*Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);},{passive:false});stage.addEventListener('dblclick',e=>{if(e.target.closest('button,select,details'))return;const r=stage.getBoundingClientRect();zoomAt(zoom*1.5,e.clientX-r.left,e.clientY-r.top);});}

 function choose(id){selected=id;storyId=stories(id)[0].id;phase=0;document.querySelectorAll('[data-map-region]').forEach(b=>{const active=b.dataset.mapRegion===id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active);});document.getElementById('map-region-select').value=id;history.replaceState(null,'',`#/map/${id}`);panel();const menu=document.querySelector('.map-unplaced');if(menu)menu.open=false;}
 document.addEventListener('click',e=>{const source=e.target.closest('[data-map-source]');if(source&&maps.maps[source.dataset.mapSource]){mapMode=source.dataset.mapSource;configureMap();try{localStorage.setItem('terra-map-source',mapMode);}catch{}const expanded=document.body.classList.contains('map-expanded');document.getElementById('main').innerHTML=render(selected,{full},read);if(expanded){document.querySelector('.map-console').classList.add('is-expanded');document.body.classList.add('map-expanded');const control=document.querySelector('[data-map-fullscreen]');control.textContent='收起';control.setAttribute('aria-label','收起全屏地图');}activate();return;}const n=e.target.closest('[data-map-region]');if(n)choose(n.dataset.mapRegion);const expand=e.target.closest('[data-map-fullscreen]');if(expand){const console=document.querySelector('.map-console'),on=console.classList.toggle('is-expanded');document.body.classList.toggle('map-expanded',on);expand.textContent=on?'收起':'全屏';expand.setAttribute('aria-label',on?'收起全屏地图':'展开全屏地图');const stage=document.getElementById('map-stage');fit=Math.min(stage.clientWidth/1200,stage.clientHeight/760)*.97;transform();}const z=e.target.closest('[data-map-zoom]');if(z){if(z.dataset.mapZoom==='reset'){zoom=1;pan={x:0,y:0};}else zoom=Math.max(.7,Math.min(4.5,zoom*(z.dataset.mapZoom==='in'?1.25:.8)));transform();}const s=e.target.closest('[data-map-story]');if(s){storyId=s.dataset.mapStory;phase=0;panel();}const p=e.target.closest('[data-map-phase]');if(p){phase=Number(p.dataset.mapPhase);panel();document.querySelector('.map-active-event')?.scrollIntoView({block:'nearest',behavior:'smooth'});}if(e.target.closest('[data-map-links]')){links=!links;const b=document.getElementById('map-link-toggle');b.setAttribute('aria-pressed',links);b.innerHTML=`<i></i>共有人物连线 ${links?'开':'关'}`;drawConnections();}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.map-console.is-expanded'))document.querySelector('[data-map-fullscreen]').click();});
 document.addEventListener('change',e=>{if(e.target.id==='map-region-select')choose(e.target.value);});
 window.addEventListener('resize',()=>{const s=document.getElementById('map-stage');if(s){fit=Math.min(s.clientWidth/1200,s.clientHeight/760)*.97;transform();}});
 window.TERRA_MAP={render,activate};
})();
